KURS = dict(
    id="u06", gebiet="upc", titel="Nichtigkeit, Widerklage und Änderung des Patents", untertitel="Art. 65 EPGÜ, Art. 138 EPÜ, R. 25 bis 30 und 42 bis 50 VerfO",
    farbe="#9d3e6e", icon="loeschung",
    beschreibung="Der Angriff auf den Rechtsbestand vor dem EPG: Nichtigkeitsklage bei der Zentralkammer und Widerklage vor der Lokalkammer, Klagebefugnis (Pari/Philips), Substantiierung und Verteidigung von Unteransprüchen (Fujifilm/Kodak), bedingte Widerklage (Emboline/AorticLab), die Nichtigkeitsgründe des Art. 138 EPÜ in der Rechtsprechung des Berufungsgerichts (expert/Seoul Viosys, Knaus Tabbert, NanoString/10x, Meril/Edwards, Abbott/Sinocare) sowie Änderung des Patents und Erwiderung (Meril/Edwards, VMR/NJOY), Aussetzung bei EPA-Einspruch und aufschiebende Wirkung.",
    kapitel=[
        dict(id="u06a", titel="Nichtigkeitsklage und Widerklage: Zulässigkeit und Verfahren", einheiten=[
            schema("u06a-0", "Prüfungsschema: Nichtigkeitsklage und Widerklage auf Nichtigerklärung", "upc_schema_nichtigkeit",
                   "Zwei Wege zum selben Ziel: die selbständige Nichtigkeitsklage bei der Zentralkammer (Art. 33 Abs. 4 EPGÜ, R. 42 ff. VerfO) und die Widerklage auf Nichtigerklärung in der Klageerwiderung vor der Lokal- oder Regionalkammer (R. 25 VerfO), über deren Schicksal die Kammer nach Art. 33 Abs. 3 EPGÜ entscheidet. Anders als im deutschen Recht gibt es keine Einspruchsfrist-Sperre: Die Nichtigkeitsklage ist auch während eines EPA-Einspruchs möglich; das Gericht kann aussetzen (R. 295 lit. a VerfO, Art. 33 Abs. 10 EPGÜ)."),
            fall("u06a-1", "Freedom to operate als Klagebefugnis",
                 "Pari entwickelt Inhalationsgeräte und will ein neues Produkt auf den Markt bringen, das in den Schutzbereich eines Patents von Philips fallen könnte. Philips hat Pari weder abgemahnt noch verklagt. Pari erhebt bei der Zentralkammer Mailand Nichtigkeitsklage. Philips rügt, Pari sei nicht „betroffen“ im Sinne des Art. 47 Abs. 6 EPGÜ, weil kein konkreter Konflikt bestehe.",
                 "Ist Pari zur Nichtigkeitsklage befugt?", True,
                 ["**Ja!** Nach Art. 47 Abs. 6 EPGÜ kann jede natürliche oder juristische Person Klage erheben, die von einem Patent **betroffen** und nach dem für sie geltenden nationalen Recht klageberechtigt ist. Betroffen ist jede Person, die ihre Freedom-to-operate klären will, also jeder, der auf dem technischen Gebiet des Patents tätig ist oder werden könnte (ZK Mailand Pari/Philips).",
                  "Eine Abmahnung, eine Verletzungsklage oder ein besonderes Rechtsschutzbedürfnis wie im deutschen Nichtigkeitsverfahren sind nicht erforderlich. Pari ist als Wettbewerberin auf dem Gebiet der Inhalationstechnik betroffen; die Klage ist zulässig. Zuständig ist die Zentralkammer (Art. 33 Abs. 4 EPGÜ), die Abteilung folgt der IPC-Klasse des Patents (Anhang II EPGÜ, R. 17.3 VerfO), es sei denn, zwischen denselben Parteien wäre bereits eine Verletzungsklage bei einer Lokalkammer anhängig."],
                 merke="Betroffen nach Art. 47 Abs. 6 EPGÜ ist, wer auf dem Gebiet tätig ist oder werden könnte (Pari/Philips).",
                 level=1, concepts=["upc_nichtigkeitsklage", "upc_zentralkammer"], norms=["Art. 47 Abs. 6 EPGÜ", "Art. 33 Abs. 4 EPGÜ", "R. 42 VerfO"], cases=["upc_cfi_pari_philips_klagebefugnis"], step="step:upc_schema_nichtigkeit.1.2"),
            fall("u06a-2", "Unteransprüche ohne Hilfsantrag",
                 "Fujifilm greift ein Patent von Kodak für Druckplatten mit einer Nichtigkeitsklage an, die sich gegen „alle Ansprüche“ richtet, aber nur den Hauptanspruch mit Entgegenhaltungen substantiiert. Kodak erwidert, die Ansprüche 1 bis 12 seien rechtsbeständig, jedenfalls aber die Kombinationen der Ansprüche 1, 4 und 7 sowie 1, 4 und 9, und benennt dafür die technischen Gründe. Einen Antrag auf Änderung des Patents nach R. 30 VerfO stellt Kodak nicht. Fujifilm meint, ohne Hilfsantrag könne Kodak Unteransprüche nicht gesondert verteidigen.",
                 "Muss der Patentinhaber einen Antrag auf Änderung des Patents stellen, um Unteransprüche oder Anspruchskombinationen gesondert zu verteidigen?", False,
                 ["**Nein!** Der Patentinhaber muss nach R. 29A lit. c VerfO in der Erwiderung hinreichend substantiiert angeben, welche Unteransprüche oder Kombinationen er für rechtsbeständig hält, und zwar in angemessener Zahl. Ein Antrag auf Änderung des Patents nach R. 30 VerfO ist dafür **nicht** nötig; er ist nur erforderlich, wenn der **Wortlaut** der Ansprüche geändert werden soll (EPG-BerG Fujifilm/Kodak).",
                  "Umgekehrt trifft den Nichtigkeitskläger eine Substantiierungslast: Er muss angeben, in welchem Umfang er die Nichtigerklärung begehrt, und dies **für jeden angegriffenen Anspruch** substantiieren (R. 25.1 lit. a bis d, R. 44 VerfO; front-loaded procedure). Wer pauschal „alle Ansprüche“ angreift, aber nur den Hauptanspruch begründet, kann die Unteransprüche nicht zu Fall bringen. Kodaks Verteidigung der Kombinationen ist zulässig, Fujifilms Angriff auf die Unteransprüche unsubstantiiert."],
                 merke="R. 29A lit. c: Unteransprüche verteidigen ja, Hilfsantrag nur bei geändertem Wortlaut (Fujifilm/Kodak).",
                 level=2, concepts=["upc_nichtigkeitsgruende", "upc_aenderung_patent", "upc_front_loaded"], norms=["R. 25 VerfO", "R. 29A VerfO", "R. 30 VerfO", "R. 44 VerfO"], cases=["upc_coa_fujifilm_kodak_nichtigkeit"], step="step:upc_schema_nichtigkeit.1.3"),
            fall("u06a-3", "Die Widerklage unter Bedingung",
                 "Emboline verklagt AorticLab vor einer Lokalkammer wegen Verletzung eines Patents für einen Embolieschutzfilter. AorticLab hält das Patent für nichtig, will aber die Widerklagegebühr sparen, falls das Gericht die Verletzung ohnehin verneint. Sie erhebt in der Klageerwiderung Widerklage auf Nichtigerklärung „für den Fall, dass das Gericht eine Verletzung feststellt“. Emboline hält die Widerklage wegen der Bedingung für unzulässig.",
                 "Darf eine Widerklage auf Nichtigerklärung unter die Bedingung gestellt werden, dass das Gericht eine Verletzung feststellt?", True,
                 ["**Ja!** Eine Widerklage auf Nichtigerklärung darf unter die Bedingung einer Verletzungsfeststellung gestellt werden (EPG-BerG Emboline/AorticLab). Die Bedingung ist eine „inter-prozedurale“ Bedingung zwischen zwei nach EPGÜ und VerfO **getrennten Klagen**; sie lässt die Anhängigkeit der Widerklage unberührt, und „das Gericht“ als Bezugspunkt meint ohne gegenteilige Angabe beide Instanzen (EPG-BerG AorticLab/Emboline).",
                  "Folgen: Weist die Lokalkammer die Verletzungsklage ab und bescheidet die Widerklage deshalb nicht, kann der Widerkläger diese Nichtentscheidung anfechten, und zwar mit einer **gesonderten, bedingten Berufung** (nicht Anschlussberufung), deren Gebühr erst fällig wird, wenn der Kläger Berufung einlegt. Stellt das Berufungsgericht die Verletzung fest, entscheidet es die Widerklage in der Regel selbst (Art. 75 Abs. 1 EPGÜ, R. 242.2 lit. b VerfO). Über die Behandlung der Widerklage entscheidet die Lokalkammer nach Art. 33 Abs. 3 EPGÜ, R. 37 VerfO."],
                 merke="Bedingte Widerklage ist zulässig; Verletzungsklage und Widerklage bleiben getrennte Klagen (Emboline/AorticLab, AorticLab/Emboline).",
                 level=3, concepts=["upc_widerklage_nichtigkeit", "upc_nichtigkeitsklage"], norms=["R. 25 VerfO", "Art. 33 Abs. 3 EPGÜ", "R. 263 VerfO", "Art. 75 EPGÜ"], cases=["upc_coa_emboline_aorticlab_bedingte_widerklage", "upc_coa_aorticlab_emboline_getrennte_klagen"], step="step:upc_schema_nichtigkeit.1.1"),
            mc("u06a-4", "Drei Optionen, EPA-Einspruch und Berufung",
               "Gegen die Verletzungsklage vor der Lokalkammer Düsseldorf wird Widerklage auf Nichtigerklärung erhoben; parallel läuft ein Einspruch beim EPA. Welche Aussage ist richtig?",
               ["Die Lokalkammer muss die Widerklage stets an die Zentralkammer verweisen, weil nur diese mit einem technisch qualifizierten Richter besetzt ist (Bifurkation)",
                "Wegen des EPA-Einspruchs ist die Widerklage unzulässig; das Gericht muss das Verfahren bis zur Entscheidung des EPA aussetzen",
                "Die Lokalkammer kann nach Art. 33 Abs. 3 EPGÜ beide Klagen selbst unter Zuweisung eines technisch qualifizierten Richters verhandeln, die Widerklage an die Zentralkammer verweisen oder mit Zustimmung der Parteien beides verweisen; eine Aussetzung wegen des EPA-Einspruchs steht in ihrem Ermessen und setzt voraus, dass die EPA-Entscheidung kurzfristig zu erwarten ist",
                "Die Berufung gegen die Entscheidung über die Widerklage hat wie jede Berufung keine aufschiebende Wirkung"], 2,
               ["**Richtig ist die dritte Aussage.** Art. 33 Abs. 3 EPGÜ gibt der Lokalkammer nach Anhörung der Parteien drei Optionen: (a) gemeinsame Verhandlung mit einem technisch qualifizierten Richter aus dem Richterpool, (b) Verweisung der Widerklage an die Zentralkammer mit Fortführung oder Aussetzung der Verletzungsklage, (c) Verweisung beider Klagen mit Zustimmung der Parteien; die Entscheidung ergeht nach R. 37 VerfO, in der Praxis wählen die Kammern fast immer Option (a). Ein paralleler EPA-Einspruch sperrt die Widerklage nicht; das Gericht **kann** nach R. 295 lit. a VerfO, Art. 33 Abs. 10 EPGÜ aussetzen, wenn eine rasche Entscheidung des EPA zu erwarten ist, oder die Beschleunigung beim EPA anregen. Über die Aussetzung eines erstinstanzlichen Verfahrens entscheidet grundsätzlich das Gericht erster Instanz, nicht das Berufungsgericht (EPG-BerG Sun Patent/Vivo).",
                "Die vierte Aussage ist falsch: Nach Art. 74 Abs. 2 EPGÜ hat die Berufung gegen Entscheidungen über Nichtigkeitsklagen und Widerklagen auf Nichtigerklärung **stets** aufschiebende Wirkung, anders als die Berufung gegen Verletzungsentscheidungen (Art. 74 Abs. 1 EPGÜ, R. 223 VerfO)."],
               level=2, concepts=["upc_widerklage_nichtigkeit", "upc_aussetzung", "upc_aufschiebende_wirkung"], norms=["Art. 33 Abs. 3 EPGÜ", "Art. 33 Abs. 10 EPGÜ", "R. 295 VerfO", "Art. 74 Abs. 2 EPGÜ"], cases=["upc_coa_sunpatent_vivo_aussetzung", "upc_coa_emboline_aorticlab_bedingte_widerklage"], step="step:upc_schema_nichtigkeit.1.4"),
        ]),
        dict(id="u06b", titel="Nichtigkeitsgründe (Art. 65 Abs. 2 EPGÜ, Art. 138 EPÜ)", einheiten=[
            intro("u06b-0", "Die Gründe kommen aus dem EPÜ, der Maßstab vom Berufungsgericht",
                  "Das EPG kann ein Patent nur aus den Gründen des **Art. 138 Abs. 1 und Art. 139 Abs. 2 EPÜ** ganz oder teilweise für nichtig erklären (Art. 65 Abs. 2 EPGÜ): fehlende Patentierbarkeit (Neuheit, erfinderische Tätigkeit, Ausschlüsse), unzureichende Offenbarung, unzulässige Erweiterung, Erweiterung des Schutzbereichs, fehlende Berechtigung. Betreffen die Gründe nur einen Teil, wird das Patent durch Änderung der Ansprüche beschränkt (Art. 65 Abs. 3 EPGÜ); es kann auch im Umfang einzelner selbständiger Ansprüche bestehen bleiben, wenn diese nicht so aufeinander aufbauen, dass der Wegfall des einen den des anderen erzwingt (LK Hamburg Avago/Tesla). Die Nichtigerklärung wirkt **ex tunc** (Art. 65 Abs. 4 EPGÜ). Die Maßstäbe hat das Berufungsgericht in wenigen Jahren geprägt: Die **Auslegung** folgt für Verletzung und Rechtsbestand denselben Regeln (NanoString/10x). Der **Offenbarungsmaßstab** „unmittelbar und eindeutig“ gilt gleichermaßen für Neuheit, unzulässige Erweiterung und Priorität; ein allgemeiner Begriff offenbart nicht ohne Weiteres alle Unterbegriffe (Knaus Tabbert), und aus schematischen Zeichnungen leitet die Fachperson keine Abmessungen ab (Pari/Philips). Bei **Teilanmeldungen** gilt Art. 123 Abs. 2 EPÜ gegenüber jeder früheren Anmeldung, auch der PCT-Stammanmeldung (expert/Seoul Viosys); die unzulässige Erweiterung ist Rechtsfrage, das Gericht darf die ganze Anmeldung heranziehen (Amgen/Regeneron). Für die **erfinderische Tätigkeit** gibt es keinen starren Aufgabe-Lösungs-Ansatz: realistischer Ausgangspunkt, Fachperson mit Aussicht auf Erfolg, „would“ statt „could“ (NanoString/10x, Meril/Edwards), Pointer für Kombinationen (Fujifilm/Kodak), keine vorschnelle Ausklammerung nichttechnischer Merkmale (Abbott/Sinocare). Die Zentralkammer Paris prüft in drei Schritten: objektive Aufgabe, Stand der Technik mit realistischen Ausgangspunkten, Naheliegen (Meril/Edwards). **Ausführbarkeit**: Die Fachperson muss den Gegenstand ohne erfinderisches Zutun und ohne unzumutbaren Aufwand nacharbeiten können; ein Weg genügt (Amgen/Regeneron).",
                  concepts=["upc_nichtigkeitsgruende", "upc_fachperson", "upc_offenbarungsgehalt"], norms=["Art. 65 Abs. 2 EPGÜ", "Art. 65 Abs. 3 EPGÜ", "Art. 65 Abs. 4 EPGÜ"], cases=["upc_cfi_avago_tesla_teilnichtigkeit", "upc_coa_nanostring_10x", "upc_coa_amgen_regeneron_auslegung"]),
            fall("u06b-1", "Die Teilanmeldung und ihre Stammanmeldung",
                 "Seoul Viosys hält ein Patent auf eine LED-Anordnung, das aus einer Teilanmeldung hervorgegangen ist; die Kette reicht über eine europäische Stammanmeldung zurück bis zu einer PCT-Anmeldung. expert greift das Patent an: Der erteilte Anspruch kombiniere zwei Merkmale, die in der PCT-Anmeldung nur getrennt in verschiedenen Ausführungsformen beschrieben seien. Seoul Viosys erwidert, maßgeblich sei allein die unmittelbar vorangehende europäische Stammanmeldung, in der die Kombination bereits enthalten sei.",
                 "Genügt es für die Prüfung der unzulässigen Erweiterung, dass die Kombination in der unmittelbar vorangehenden Stammanmeldung offenbart ist?", False,
                 ["**Nein!** Unzulässige Erweiterung (Art. 138 Abs. 1 lit. c EPÜ, Art. 65 Abs. 2 EPGÜ) liegt vor, wenn der Gegenstand des erteilten Anspruchs über den Inhalt der ursprünglichen Anmeldung hinausgeht. Maßgeblich ist, was die Fachperson objektiv am Anmeldetag mit ihrem Fachwissen **unmittelbar und eindeutig** der Gesamtheit der Anmeldung entnimmt, einschließlich implizit Offenbartem. Bei Patenten aus Teilanmeldungen gilt dies gegenüber **jeder** früheren Anmeldung der Kette, also auch gegenüber der PCT-Stammanmeldung (EPG-BerG expert/Seoul Viosys).",
                  "Ist die Merkmalskombination in der PCT-Anmeldung nur in getrennten Ausführungsformen beschrieben, ohne dass die Fachperson die Kombination als offenbart mitliest, geht der erteilte Anspruch über ihren Inhalt hinaus. Die Prüfung ist Rechtsfrage auf Grundlage der vorgetragenen Tatsachen, das Gericht darf die gesamte Anmeldung heranziehen und aus eigener Sachkunde feststellen, dass eine Offenbarung fehlt (Amgen/Regeneron). Das Patent ist insoweit für nichtig zu erklären, sofern Seoul Viosys es nicht durch Änderung (R. 30, R. 50 VerfO) auf eine offenbarte Fassung beschränkt."],
                 merke="Teilanmeldung: Art. 123 Abs. 2 EPÜ ist gegenüber jeder früheren Anmeldung zu wahren (expert/Seoul Viosys).",
                 level=2, concepts=["upc_unzulaessige_erweiterung", "upc_fachperson"], norms=["Art. 65 Abs. 2 EPGÜ"], cases=["upc_coa_expert_seoulviosys_erweiterung", "upc_coa_amgen_regeneron_auslegung"], step="step:upc_schema_nichtigkeit.2.4"),
            fall("u06b-2", "Der Oberbegriff in der Entgegenhaltung",
                 "Knaus Tabbert verteidigt ein Patent für ein Bauteil eines Wohnwagens, dessen Anspruch einen bestimmten Werkstoff mit einer bestimmten Struktur verlangt. Die Nichtigkeitsklägerin hält eine Druckschrift entgegen, die für dasselbe Bauteil allgemein „Kunststoff“ nennt, ohne die konkrete Struktur zu erwähnen. Sie meint, der Oberbegriff „Kunststoff“ offenbare alle darunter fallenden Werkstoffe und Strukturen und nehme den Anspruch neuheitsschädlich vorweg.",
                 "Offenbart ein allgemeiner Begriff in einer Vorveröffentlichung neuheitsschädlich alle darunter fallenden spezifischen Ausführungen?", False,
                 ["**Nein!** Neuheitsschädlich ist nur, was die Fachperson einer Vorveröffentlichung bei aufmerksamer Lektüre **unmittelbar und eindeutig** entnimmt und als selbstverständlich mitliest. Ein allgemeiner Begriff offenbart nicht ohne Weiteres alle darunter fallenden, nicht genannten spezifischen Unterbegriffe (EPG-BerG Knaus Tabbert).",
                  "Die Entgegenhaltung nennt weder den konkreten Werkstoff noch die Struktur; sie nimmt den Anspruch nicht vorweg. Der Angriff verlagert sich damit auf die erfinderische Tätigkeit: Dort ist zu fragen, ob die Fachperson, die erkennt, dass sich das Problem in einem benachbarten Gebiet ähnlich stellt, dortige Experten hinzuzieht und mit Aussicht auf Erfolg zur beanspruchten Lösung gelangen würde. Derselbe Offenbarungsmaßstab gilt für unzulässige Erweiterung und Priorität; product-by-process-Merkmale sind Sachmerkmale, bei denen zu prüfen ist, ob sich das Verfahren in Eigenschaften des Erzeugnisses niederschlägt."],
                 merke="Oberbegriff offenbart nicht den Unterbegriff; Offenbarung heißt unmittelbar und eindeutig (Knaus Tabbert).",
                 level=2, concepts=["upc_offenbarungsgehalt", "upc_fachperson"], norms=["Art. 65 Abs. 2 EPGÜ"], cases=["upc_coa_knaus_tabbert_altfaelle", "upc_cfi_pari_philips_klagebefugnis"], step="step:upc_schema_nichtigkeit.2.2"),
            mc("u06b-3", "Erfinderische Tätigkeit vor dem EPG",
               "Welche Aussage zur Prüfung der erfinderischen Tätigkeit entspricht der Rechtsprechung des EPG?",
               ["Es genügt, dass die Fachperson vom Stand der Technik ausgehend zur Erfindung hätte gelangen können; auf die Aussicht auf Erfolg kommt es nicht an",
                "Merkmale, die für sich genommen nichttechnisch sind, bleiben bei der Prüfung der erfinderischen Tätigkeit stets außer Betracht",
                "Ausgangspunkt ist ein realistischer Stand der Technik; die Fachperson muss mit Aussicht auf Erfolg zur Erfindung gelangen, nicht nur gelangen können, und für die Kombination mit einer weiteren Schrift bedarf es einer Anregung, die sich nicht allein aus deren Inhalt herleiten lässt",
                "Das Berufungsgericht wendet den Aufgabe-Lösungs-Ansatz des EPA in allen Schritten zwingend an"], 2,
               ["**Richtig ist die dritte Aussage.** Das Berufungsgericht wendet keinen starren Aufgabe-Lösungs-Ansatz an: Ausgangspunkt ist ein **realistischer** Stand der Technik, und die Fachperson muss von dort mit **Aussicht auf Erfolg** zur Erfindung gelangen („would“), nicht nur gelangen können („could“) (NanoString/10x, Meril/Edwards). Ohne Anregung („pointer“), einen Ausgangspunkt mit einer weiteren Schrift zu kombinieren, lässt sich die Motivation nicht aus dem Inhalt der Kombinationsschrift selbst herleiten (Fujifilm/Kodak). Die Zentralkammer Paris prüft in Anlehnung an den PSA in drei Schritten: objektive Aufgabe im Lichte der Patentschrift, Stand der Technik mit einem oder mehreren realistischen Ausgangspunkten (Sache der Parteien), Naheliegen bei Betrachtung der Erfindung als Ganzes (ZK Paris Meril/Edwards).",
                "Die zweite Aussage ist falsch: Ein Merkmal ist nicht schon deshalb auszuklammern, weil es für sich genommen nichttechnisch wäre; es kann durch Zusammenwirken mit den übrigen Merkmalen zum technischen Charakter beitragen, weshalb die Merkmale gemeinsam zu würdigen sind (Abbott/Sinocare). Die erste und die vierte Aussage widersprechen NanoString/10x und Meril/Edwards."],
               level=3, concepts=["upc_erfinderische_taetigkeit", "upc_fachperson"], norms=["Art. 65 Abs. 2 EPGÜ"], cases=["upc_coa_meril_edwards_parteien", "upc_cfi_meril_edwards_erfinderisch", "upc_coa_abbott_sinocare_erfinderisch"], step="step:upc_schema_nichtigkeit.2.3"),
        ]),
        dict(id="u06c", titel="Verteidigung: Änderung des Patents und Erwiderung", einheiten=[
            intro("u06c-0", "Hilfsanträge nach R. 30 und R. 50 VerfO",
                  "Der Patentinhaber verteidigt sich auf zwei Ebenen. Erstens mit der **Erwiderung** (R. 29A VerfO bei der Widerklage, R. 49, 50.1 VerfO bei der Nichtigkeitsklage): Tatsachen, Beweise, Gründe, warum die Klage abzuweisen ist, und die Angabe, welche Unteransprüche oder Kombinationen er für rechtsbeständig hält (Fujifilm/Kodak). Zweitens mit dem **Antrag auf Änderung des Patents** (R. 30.1, R. 50.2 VerfO), der die geänderten Ansprüche, gegebenenfalls Hilfsanträge in angemessener Zahl, die Begründung nach Art. 84, 123 Abs. 2 und 3 EPÜ und die Angabe enthalten muss, ob die Änderung bedingt oder unbedingt ist. Der Antrag gehört in die Erwiderung; **spätere Anträge** sind nur mit Erlaubnis des Gerichts zulässig (R. 30.2 VerfO), das prüft, ob die Änderung bei angemessener Sorgfalt nicht früher möglich war und die Gegenseite nicht unangemessen behindert wird; das Gericht erster Instanz hat dabei Ermessen, die Kontrolle durch das Berufungsgericht ist beschränkt (Meril/Edwards). Auf den Änderungsantrag folgt die **Erwiderung des Klägers** (R. 32, R. 43.3 VerfO) mit Ausführungen nach R. 44 lit. d bis h; sie darf keine neuen Nichtigkeitsgründe oder Entgegenhaltungen gegen die erteilte Fassung einführen, es sei denn, eine Klageänderung nach R. 263 VerfO wird zugelassen (VMR/NJOY). Läuft ein anderes Verfahren zu dem Patent, ist die zuständige Stelle über den Änderungsantrag zu unterrichten (R. 30.3 VerfO). Am Ende steht die Entscheidung nach Art. 65 Abs. 3 EPGÜ: Beschränkung durch die geänderten Ansprüche und teilweise Nichtigerklärung.",
                  concepts=["upc_aenderung_patent", "upc_nichtigkeitsklage", "upc_front_loaded"], norms=["R. 30 VerfO", "R. 50 VerfO", "R. 43 VerfO", "R. 29A VerfO"], cases=["upc_coa_meril_edwards_parteien", "upc_coa_vmr_njoy_aenderung", "upc_coa_fujifilm_kodak_nichtigkeit"]),
            fall("u06c-1", "Der Hilfsantrag nach der Duplik",
                 "Edwards hat in der Erwiderung auf die Widerklage von Meril vier Hilfsanträge gestellt. Nach Abschluss des schriftlichen Verfahrens, kurz vor der Zwischenanhörung, reicht Edwards drei weitere Hilfsanträge ein, die auf Einwände reagieren, die Meril bereits in der Widerklage erhoben hatte. Edwards begründet nicht, warum die Anträge nicht früher möglich waren. Die Lokalkammer lässt sie nicht zu; Edwards legt Berufung ein.",
                 "Muss das Berufungsgericht die späten Hilfsanträge zulassen, weil sie inhaltlich auf die Widerklage reagieren?", False,
                 ["**Nein!** Der Antrag auf Änderung des Patents gehört in die Erwiderung auf die Widerklage (R. 30.1 VerfO); **spätere Anträge** können nur mit Erlaubnis des Gerichts zugelassen werden (R. 30.2, R. 50.2 VerfO). Das Gericht prüft, ob die Änderung bei angemessener Sorgfalt nicht früher möglich war und ob die Gegenseite unangemessen behindert wird. Reagieren die Anträge auf Einwände, die schon in der Widerklage standen, fehlt es an einem Grund für die Verspätung (EPG-BerG Meril/Edwards).",
                  "Das Gericht erster Instanz hat bei dieser Entscheidung **Ermessen**; das Berufungsgericht überprüft nur, ob das Ermessen fehlerfrei ausgeübt wurde, nicht, ob es selbst anders entschieden hätte. Da Edwards die Verspätung nicht begründet hat, ist die Nichtzulassung ermessensfehlerfrei. Hintergrund ist das front-loaded-Verfahren (Präambel VerfO Nr. 7): Alle Verteidigungslinien, auch Hilfsanträge, gehören in den ersten Schriftsatz."],
                 merke="Hilfsanträge in die Erwiderung; spätere nur mit Erlaubnis und Begründung, Ermessen der ersten Instanz (Meril/Edwards).",
                 level=2, concepts=["upc_aenderung_patent", "upc_front_loaded"], norms=["R. 30 VerfO", "R. 50 VerfO", "R. 263 VerfO"], cases=["upc_coa_meril_edwards_parteien"], step="step:upc_schema_nichtigkeit.3"),
            fall("u06c-2", "Neue Entgegenhaltungen in der Erwiderung auf den Änderungsantrag",
                 "NJOY greift ein Patent von VMR für E-Zigaretten mit einer Nichtigkeitsklage an, die sich auf drei Entgegenhaltungen stützt. VMR beantragt in der Klageerwiderung hilfsweise eine geänderte Anspruchsfassung. In der Erwiderung auf den Änderungsantrag nach R. 43.3 VerfO führt NJOY zwei neue Druckschriften ein und macht mit ihnen erstmals mangelnde Neuheit des Patents **in der erteilten Fassung** geltend. Einen Antrag auf Klageänderung stellt NJOY nicht.",
                 "Darf der Nichtigkeitskläger in der Erwiderung auf den Änderungsantrag neue Nichtigkeitsgründe gegen das Patent in erteilter Fassung einführen?", False,
                 ["**Nein!** Auf einen Antrag auf Änderung des Patents folgt die Erwiderung nach R. 43.3 VerfO, die Ausführungen nach R. 44 lit. d bis h und hilfsweise Nichtverletzungsargumente enthalten kann. Sie eröffnet dem Kläger aber **nicht** die Möglichkeit, neue Nichtigkeitsgründe oder neue Entgegenhaltungen gegen das Patent **in erteilter Fassung** einzuführen, es sei denn, eine Klageänderung wird nach R. 263 VerfO zugelassen (EPG-BerG VMR/NJOY).",
                  "Im front-loaded-Verfahren müssen alle Nichtigkeitsgründe und Entgegenhaltungen in die Klage (R. 44 VerfO); neue Argumente sind nur nach den Umständen zuzulassen. Die Fairness kann allerdings neue **Beweise zum allgemeinen Fachwissen** als Reaktion auf die Klageerwiderung erlauben, denn das Fachwissen ist beweisbedürftige Tatsache. Die beiden Druckschriften bleiben gegen die erteilte Fassung unberücksichtigt; gegen die **geänderte** Fassung darf NJOY sie verwenden, weil die Erwiderung genau dafür da ist."],
                 merke="R. 43.3-Erwiderung richtet sich gegen die geänderte Fassung; neue Angriffe auf die erteilte Fassung nur über R. 263 (VMR/NJOY).",
                 level=3, concepts=["upc_aenderung_patent", "upc_klageaenderung", "upc_beweismittel_beweislast"], norms=["R. 43 VerfO", "R. 44 VerfO", "R. 263 VerfO", "R. 32 VerfO"], cases=["upc_coa_vmr_njoy_aenderung"], step="step:upc_schema_nichtigkeit.3"),
        ]),
    ],
)
